// node test/gif.test.mjs (from this folder) -- the GIF writer, without a browser. It is read back three
// ways: by a decoder written here from the spec, and by Pillow and ffmpeg when they are installed (each
// says SKIPPED when it is not). A decoder of our own could share the writer's misreading of the format;
// the other two cannot.
// THIS SECTION GENERATED BY CLAUDE
import { makeGif, quantize, mapPixels, lzw } from '../gif.js'
import assert from 'node:assert/strict'
import { writeFileSync, mkdtempSync, rmSync } from 'node:fs'
import { join } from 'node:path'
import { tmpdir } from 'node:os'
import { execFileSync } from 'node:child_process'

// ---- a reader, from the GIF89a spec: the blocks, and LZW decoded with the decoder's own widening rule ----
let readGif = bytes => {
    let o = 0, u8 = () => bytes[o++], u16 = () => { let v = bytes[o] | bytes[o + 1] << 8; o += 2; return v }
    let sub = () => { let out = []; for (let n; (n = u8());) { for (let j = 0; j < n; j++) out.push(bytes[o++]) } return out }
    assert.equal(new TextDecoder().decode(bytes.slice(0, 6)), 'GIF89a'); o = 6
    let W = u16(), H = u16(), packed = u8(); o += 2
    assert.equal(packed & 0x80, 0, 'no global table')
    let frames = [], loop = null, delay = null
    for (;;) {
        let b = u8()
        if (b == 0x3B) break
        if (b == 0x21) {
            let label = u8()
            if (label == 0xF9) { u8(); u8(); delay = u16(); u8(); u8() }
            else if (label == 0xFF) { let id = sub(); loop = id.length >= 14 ? id[12] | id[13] << 8 : loop }
            else sub()
            continue
        }
        assert.equal(b, 0x2C, `a block at ${o - 1}`)
        let x = u16(), y = u16(), w = u16(), h = u16(), p = u8()
        assert.ok(p & 0x80, 'a local table'); assert.deepEqual([x, y, w, h], [0, 0, W, H])
        let n = 2 << (p & 7), table = bytes.slice(o, o + 3 * n); o += 3 * n
        let min = u8(), data = sub()
        // decode
        let clear = 1 << min, eoi = clear + 1, size, next, dict, prev = null, idx = []
        let reset = () => { size = min + 1; next = eoi + 1; dict = []; for (let j = 0; j < clear; j++) dict[j] = [j]; prev = null }
        reset()
        let acc = 0, nb = 0, q = 0, ended = false
        while (!ended) {
            while (nb < size) { assert.ok(q < data.length, 'codes run out before the end code'); acc |= data[q++] << nb; nb += 8 }
            let code = acc & ((1 << size) - 1); acc >>>= size; nb -= size
            if (code == clear) { reset(); continue }
            if (code == eoi) { ended = true; break }
            let entry = code < next && dict[code] ? dict[code] : code == next && prev ? [...prev, prev[0]] : null
            assert.ok(entry, `code ${code} with ${next} defined`)
            idx.push(...entry)
            if (prev && next < 4096) { dict[next++] = [...prev, entry[0]]; if (next == (1 << size) && size < 12) size++ }
            prev = entry
        }
        assert.equal(idx.length, W * H, 'every pixel decoded')
        let rgb = new Uint8Array(3 * W * H)
        idx.forEach((j, i) => { assert.ok(j < n); rgb.set(table.slice(3 * j, 3 * j + 3), 3 * i) })
        frames.push({ delay, rgb })
    }
    assert.equal(o, bytes.length, 'nothing after the trailer')
    return { W, H, loop, frames }
}

let encode = async (opts, frames) => {
    let g = makeGif(opts)
    for (let [rgba, i] of frames) await g.frame(rgba, i)
    return new Uint8Array(await (await g.finish()).arrayBuffer())
}
let rgbaOf = (w, h, f) => {
    let a = new Uint8Array(4 * w * h)
    for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) { let c = f(x, y), p = 4 * (y * w + x); a[p] = c[0]; a[p + 1] = c[1]; a[p + 2] = c[2]; a[p + 3] = 255 }
    return a
}
let rgbOf = rgba => rgba.filter((_, i) => i % 4 != 3)
// bytes equal, or the first that differs -- assert.deepEqual's diff of two large arrays runs out of memory
let same = (a, b, what) => {
    assert.equal(a.length, b.length, `${what}: ${a.length} bytes, not ${b.length}`)
    for (let i = 0; i < a.length; i++) if (a[i] != b[i]) assert.fail(`${what}: byte ${i} is ${a[i]}, not ${b[i]}`)
}

// ---- 1. exact: 256 colours, one to a 5-bit bin, as noise -- every palette entry exact, the LZW table
//         filling and starting over many times (256 x 256 noise is far past 4096 codes)
let colour = j => [(j & 7) << 5, ((j >> 3) & 7) << 5, (j >> 6) << 6]
let seed = 1, rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff
let noise = rgbaOf(256, 256, () => colour(Math.floor(rnd() * 256)))
let { palette, n } = quantize(noise)
assert.equal(n, 256, 'a box for every colour')
let exact = await encode({ width: 256, height: 256, fps: 10, dither: false }, [[noise, 0]])
let G = readGif(exact)
assert.deepEqual([G.W, G.H, G.loop, G.frames.length], [256, 256, 0, 1])
same(G.frames[0].rgb, rgbOf(noise), 'noise read back')

// a picture of one colour, of two, a single pixel, and runs: the edges of the table size and of LZW
for (let [w, h, f] of [[1, 1, () => [9, 8, 7]], [5, 3, () => [200, 10, 10]], [17, 9, x => x & 1 ? [0, 0, 0] : [255, 255, 255]],
    [300, 2, x => colour(x >> 4)], [64, 64, () => [0, 0, 0]]]) {
    let px = rgbaOf(w, h, f)
    let r = readGif(await encode({ width: w, height: h, fps: 10, dither: false }, [[px, 0]]))
    same(r.frames[0].rgb, rgbOf(px), `${w}x${h} read back`)
}
// the LZW stream on its own: indices 0..3 at the smallest code size, all one index for a long run
for (let idx of [new Uint8Array([0, 1, 2, 3, 3, 3, 0]), new Uint8Array(100000)]) assert.ok(lzw(idx, 2).length > 2)

// ---- 2. a gradient: dithered, the colours average to the picture; undithered, every pixel near it
let W = 160, H = 90
let grad = t => rgbaOf(W, H, (x, y) => [x * 255 / (W - 1), y * 255 / (H - 1), (128 + 100 * Math.sin(t + x / 20)) | 0])
let film = Array.from({ length: 10 }, (_, i) => [grad(i / 3), i])
let gif30 = await encode({ width: W, height: H, fps: 30 }, film)
G = readGif(gif30)
assert.equal(G.frames.length, 10)
assert.deepEqual(G.frames.map(f => f.delay), [3, 4, 3, 3, 4, 3, 3, 4, 3, 3], '30 fps keeps time in centiseconds')
let meanErr = (a, b) => { let s = 0; for (let i = 0; i < a.length; i++) s += Math.abs(a[i] - b[i]); return s / a.length }
let blockErr = (a, b, k = 4) => {          // the error of k x k block means: what dithering is for
    let s = 0, m = 0
    for (let y = 0; y + k <= H; y += k) for (let x = 0; x + k <= W; x += k) for (let c = 0; c < 3; c++) {
        let sa = 0, sb = 0
        for (let v = 0; v < k; v++) for (let u = 0; u < k; u++) { let i = 3 * ((y + v) * W + x + u) + c; sa += a[i]; sb += b[i] }
        s += Math.abs(sa - sb) / (k * k); m++
    }
    return s / m
}
let src0 = rgbOf(film[0][0])
let plain = readGif(await encode({ width: W, height: H, fps: 30, dither: false }, [film[0]])).frames[0].rgb
let e = { plain: meanErr(plain, src0), dithered: meanErr(G.frames[0].rgb, src0), plainBlock: blockErr(plain, src0), ditheredBlock: blockErr(G.frames[0].rgb, src0) }
// the bound is Pillow's on this frame (Image.quantize(256), no dither: median cut 5.27, max coverage 4.72,
// fast octree 7.23 -- measured 2026-10-09); this writer gave 4.82 then
assert.ok(e.plain < 5.3, `undithered mean error ${e.plain}, worse than Pillow's median cut`)
assert.ok(e.ditheredBlock < 1.5 && e.ditheredBlock <= e.plainBlock, `dithered block error ${e.ditheredBlock} vs ${e.plainBlock}`)
console.log('gradient, mean |error| per channel:', Object.entries(e).map(([k, v]) => `${k} ${v.toFixed(2)}`).join(', '))

// ---- 3. the clock: 60 fps drops every other frame rather than play at 10 cs; 25 fps is 4 cs; a range
//         starting later keeps its own clock; a frame index out of order is refused
let sixty = readGif(await encode({ width: 8, height: 8, fps: 60 }, Array.from({ length: 12 }, (_, i) => [grad(i).slice(0, 256), i])))
assert.ok(sixty.frames.every(f => f.delay >= 2), 'no delay a browser would slow down')
assert.equal(sixty.frames.reduce((s, f) => s + f.delay, 0), 20, '12 frames at 60 fps are 20 cs')
assert.deepEqual(readGif(await encode({ width: 8, height: 8, fps: 25 }, [0, 1, 2].map(i => [grad(i).slice(0, 256), i]))).frames.map(f => f.delay), [4, 4, 4])
await assert.rejects(encode({ width: 8, height: 8 }, [[grad(0).slice(0, 256), 1], [grad(0).slice(0, 256), 0]]), /after frame/)
await assert.rejects(encode({ width: 8, height: 8 }, [[new Uint8Array(4), 0]]), /pixels/)
assert.throws(() => makeGif({ width: 70000, height: 8 }), /cannot be/)
assert.equal(readGif(await encode({ width: 8, height: 8, loop: null }, [[grad(0).slice(0, 256), 0]])).loop, null, 'loop: null plays once')
assert.equal(readGif(await encode({ width: 8, height: 8 }, [])).frames.length, 0, 'stopped before a frame: an empty GIF, not a crash')

// ---- 4. streamed: the same bytes, written in order, finish() returning null
let parts = [], g = makeGif({ width: W, height: H, fps: 30, write: async b => { await null; parts.push(b) } })
for (let [px, i] of film) await g.frame(px, i)
assert.equal(await g.finish(), null)
same(new Uint8Array(Buffer.concat(parts)), gif30, 'streamed against collected')

// ---- 5. other decoders
let dir = mkdtempSync(join(tmpdir(), 'gif-test-')), file = join(dir, 'film.gif'), noiseFile = join(dir, 'noise.gif')
writeFileSync(file, gif30); writeFileSync(noiseFile, exact)
try {
    let py = `
import sys
from PIL import Image
im = Image.open(sys.argv[1]); out = []
for i in range(im.n_frames):
    im.seek(i); out.append(str(im.info.get('duration')))
print(im.n_frames, im.info.get('loop'), ' '.join(out))
im = Image.open(sys.argv[2]).convert('RGB'); print(im.tobytes().hex())`
    let out = null
    try { out = execFileSync('python3', ['-c', py, file, noiseFile], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], maxBuffer: 1 << 26 }) }
    catch (err) { console.log('(Pillow check SKIPPED:', String(err.stderr || err.message).trim().split('\n').pop() + ')') }
    if (out) {
        let [head, hex] = out.trim().split('\n')
        assert.equal(head, '10 0 30 40 30 30 40 30 30 40 30 30', 'Pillow: frames, loop, durations in ms')
        assert.equal(hex, Buffer.from(rgbOf(noise)).toString('hex'), 'Pillow reads the noise exactly')
        console.log('Pillow reads it the same')
    }
    let probe = null
    try { probe = execFileSync('ffprobe', ['-v', 'error', '-count_frames', '-select_streams', 'v:0', '-show_entries', 'stream=nb_read_frames,width,height', '-of', 'csv=p=0', file], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }) }
    catch (err) { console.log('(ffmpeg check SKIPPED:', String(err.stderr || err.message).trim().split('\n').pop() + ')') }
    if (probe) {
        assert.equal(probe.trim(), `${W},${H},10`, 'ffprobe: size and frames')
        // one frame: ffmpeg repeats a still to its output rate otherwise
        let raw = execFileSync('ffmpeg', ['-v', 'error', '-i', noiseFile, '-frames:v', '1', '-f', 'rawvideo', '-pix_fmt', 'rgb24', '-'], { maxBuffer: 1 << 26, stdio: ['ignore', 'pipe', 'pipe'] })
        same(new Uint8Array(raw), rgbOf(noise), 'ffmpeg reading the noise')
        console.log('ffmpeg reads it the same')
    }
} finally { rmSync(dir, { recursive: true, force: true }) }

console.log('gif: all passed')
